```json
{
  "stops": [
    {
      "poi_id": "p95",
      "kind": "meal",
      "must_do_id": "m1",
      "note": "Tô mì Quảng đậm đà, thịt heo tôm tươi, ăn kèm bánh tráng giòn rụm."
    },
    {
      "poi_id": "p211",
      "kind": "activity",
      "must_do_id": null,
      "note": "Dạo phố cổ rêu phong, ngắm mái ngói âm dương và những bức tường vàng nắng."
    },
    {
      "poi_id": "p208",
      "kind": "activity",
      "must_do_id": null,
      "note": "Chùa Cầu cong cong soi bóng nước, góc nào cũng ra ảnh đẹp."
    },
    {
      "poi_id": "p16",
      "kind": "activity",
      "must_do_id": null,
      "note": "Cát trắng, sóng hiền, nằm dài nghe gió biển An Bàng thổi qua hàng dừa."
    },
    {
      "poi_id": "p296",
      "kind": "meal",
      "must_do_id": null,
      "note": "Quán nhỏ ấm cúng, gọi món nướng trong nồi đất rồi nhâm nhi cùng ban nhạc đêm."
    }
  ]
}
```

