    },
    {
      "poi_id": "p144",
      "kind": "activity",
      "must_do_id": null,
      "note": "Leo lên đỉnh Bàn Cờ, phóng tầm mắt ra biển xanh, chỗ này chụp ảnh đẹp khỏi bàn."
    },
    {
      "poi_id": "p86",
      "kind": "meal",
